// Compare generated bytes, never execute downloaded artifacts or trust their hashes.
import { cpSync, lstatSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { digest, json } from './pack.mjs';
import { root } from './cli.mjs';

const revisionPattern = /^[0-9a-f]{40}$/;
const pagePattern = /^[a-z][a-z0-9-]*$/;
function demand(ok, message) { if (!ok) throw new Error(message); }
function regular(path, directory = false) {
  const stat = lstatSync(path);
  demand(!stat.isSymbolicLink() && (directory ? stat.isDirectory() : stat.isFile()), `Nonregular artifact path: ${path}`);
}
export function safePath(path) {
  demand(typeof path === 'string' && /^(?:index\.ts|[a-z][a-z0-9-]*\.(?:png|json))$/.test(path)
    && !/^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])\./.test(path), `Unsafe artifact path: ${path}`);
  return path;
}
function exactKeys(value, keys, label) {
  demand(value && typeof value === 'object' && !Array.isArray(value)
    && JSON.stringify(Object.keys(value).sort()) === JSON.stringify([...keys].sort()), `Invalid ${label} fields`);
}
function samePaths(actual, expected, label) {
  const missing = expected.filter((p) => !actual.includes(p));
  const extra = actual.filter((p) => !expected.includes(p));
  demand(!missing.length && !extra.length, `${label}: missing [${missing.join(', ')}]; unexpected [${extra.join(', ')}]`);
}
export function createManifest(generated, revision) {
  demand(revisionPattern.test(revision), 'Revision must be a full lowercase Git SHA');
  regular(generated, true);
  const actual = readdirSync(generated).sort();
  for (const name of actual) { safePath(name); regular(join(generated, name)); }
  demand(actual.includes('budget.json'), 'Missing generated output: budget.json');
  const report = JSON.parse(readFileSync(join(generated, 'budget.json'), 'utf8'));
  demand(Number.isSafeInteger(report.frameCount) && report.frameCount > 0
    && Array.isArray(report.pages) && report.pages.length > 0, 'Invalid generated budget/pages');
  const names = report.pages.map((page) => {
    demand(page && typeof page.name === 'string' && pagePattern.test(page.name), 'Unsafe atlas page name');
    return page.name;
  });
  demand(new Set(names).size === names.length, 'Duplicate atlas page name');
  const expected = ['budget.json', 'index.ts', ...names.flatMap((name) => [name + '.json', name + '.png'])].sort();
  samePaths(actual, expected, 'Generated outputs');
  const files = expected.map((path) => {
    const bytes = readFileSync(join(generated, safePath(path)));
    return { path, size: bytes.length, sha256: digest(bytes) };
  });
  for (const page of report.pages) {
    for (const [suffix, key] of [['.png', 'pngSha256'], ['.json', 'metadataSha256']]) {
      const file = files.find((f) => f.path === page.name + suffix);
      demand(file.sha256 === page[key], `${file.path}: stale budget hash`);
    }
  }
  demand(files.find((f) => f.path === 'index.ts').sha256 === report.indexSha256, 'index.ts: stale budget hash');
  return { version: 1, revision, files };
}
export function writeArtifact(generated, output, revision) {
  const manifest = createManifest(generated, revision);
  const source = resolve(generated), target = resolve(output);
  demand(target !== source && !target.startsWith(source + '/') && !target.startsWith(source + '\\'), 'Artifact output must be outside generated inputs');
  mkdirSync(output, { recursive: true }); regular(output, true);
  demand(readdirSync(output).length === 0, 'Artifact output must be empty; no files are overwritten');
  mkdirSync(join(output, 'generated'));
  for (const file of manifest.files) cpSync(join(generated, file.path), join(output, 'generated', file.path));
  writeFileSync(join(output, 'manifest.json'), json(manifest));
  readArtifact(output); // Rehash the copied bytes before declaring a successful upload input.
  return manifest;
}
export function readArtifact(directory) {
  regular(directory, true);
  samePaths(readdirSync(directory).sort(), ['generated', 'manifest.json'], 'Artifact root');
  regular(join(directory, 'manifest.json'));
  const manifest = JSON.parse(readFileSync(join(directory, 'manifest.json'), 'utf8'));
  exactKeys(manifest, ['version', 'revision', 'files'], 'manifest');
  demand(manifest.version === 1 && revisionPattern.test(manifest.revision) && Array.isArray(manifest.files), 'Invalid manifest version/revision/files');
  const seen = new Set();
  for (const file of manifest.files) {
    exactKeys(file, ['path', 'size', 'sha256'], 'manifest file'); safePath(file.path);
    demand(!seen.has(file.path), `Duplicate manifest path: ${file.path}`); seen.add(file.path);
    demand(Number.isSafeInteger(file.size) && file.size >= 0 && /^[0-9a-f]{64}$/.test(file.sha256), `Invalid hash/size: ${file.path}`);
  }
  const actual = createManifest(join(directory, 'generated'), manifest.revision);
  samePaths(manifest.files.map((f) => f.path), actual.files.map((f) => f.path), 'Manifest outputs');
  for (const file of actual.files) {
    const declared = manifest.files.find((f) => f.path === file.path);
    demand(declared.size === file.size && declared.sha256 === file.sha256, `${file.path}: manifest does not match actual bytes`);
  }
  demand(JSON.stringify(manifest.files.map((f) => f.path)) === JSON.stringify(actual.files.map((f) => f.path)), 'Manifest paths are not in canonical order');
  return actual;
}
export function compareArtifacts(left, right) {
  const a = readArtifact(left), b = readArtifact(right);
  demand(a.revision === b.revision, 'Artifact revisions differ');
  samePaths(a.files.map((f) => f.path), b.files.map((f) => f.path), 'Cross-OS outputs');
  const differences = a.files.filter((file, i) => file.sha256 !== b.files[i].sha256 || file.size !== b.files[i].size).map((f) => f.path);
  demand(!differences.length, `Cross-OS byte mismatch: ${differences.join(', ')}`);
  return { revision: a.revision, files: a.files.length, byteIdentical: true, comparedFiles: a.files };
}
function main(args) {
  const [mode, ...rest] = args;
  if (mode === 'manifest') {
    demand(rest.length === 2 || rest.length === 4, 'Usage: manifest --revision SHA [--output DIR]');
    demand(rest[0] === '--revision' && (rest.length === 2 || rest[2] === '--output'), 'Invalid manifest arguments');
    const generated = join(root, 'frontend/src/world-room/generated');
    return rest.length === 4 ? writeArtifact(generated, rest[3], rest[1]) : createManifest(generated, rest[1]);
  }
  demand(mode === 'compare' && rest.length === 2, 'Usage: compare WINDOWS_ARTIFACT LINUX_ARTIFACT');
  return compareArtifacts(...rest);
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try { console.log(json(main(process.argv.slice(2))).trimEnd()); }
  catch (error) { console.error(error.message); process.exitCode = 1; }
}
